/**
 * 自愈动作显示名翻译。
 *
 * 后端预置（builtin）动作的 name/description 存的是 i18n key
 * （heal.builtin.<action_id>.name），前端渲染时翻译；
 * 自定义动作 name 是用户输入，原样显示。
 * 历史数据（旧中文名）取不到 key 时 fallback 原样，不崩。
 */
import i18n from '@/locales'

interface ActionLike {
  action_id: string
  name: string
  is_builtin?: boolean
}

export function actionDisplayName(action: ActionLike): string {
  if (action.is_builtin === false) {
    return action.name
  }
  const key = `heal.builtin.${action.action_id}.name`
  if (i18n.global.te(key)) {
    return i18n.global.t(key)
  }
  // 取不到 key：历史中文数据或自定义动作，原样显示
  return action.name
}

export function actionDisplayDescription(action: { action_id: string; description?: string | null }): string {
  const key = `heal.builtin.${action.action_id}.description`
  if (i18n.global.te(key)) {
    return i18n.global.t(key)
  }
  return action.description || ''
}
